-- PT122-S1-Q2. Batch 03.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch03$PT122-S1-Q2$batch03$ AND q.stimulus=$batch03$A study of plaque buildup on teeth used three randomly assigned groups of people who brushed their teeth twice a day for a year. People in Group 1 used the same toothbrush all year. People in Group 2 used the same toothbrush all year but sterilized it each month. People in Group 3 used a new, sterile toothbrush each month. At the end of the year, people in Groups 1 and 2 had the same amount of plaque buildup as each other, while people in Group 3 had less plaque buildup.$batch03$ AND q.prompt=$batch03$Which one of the following, if true, most helps to explain the relative amounts of plaque buildup found in the three groups?$batch03$ AND q.correct_choice=$batch03$B$batch03$) THEN RAISE EXCEPTION 'Question changed: PT122-S1-Q2'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch03$PT122-S1-Q2$batch03$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT122-S1-Q2'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch03$PT122-S1-Q2$batch03$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch03$Given that$batch03$, $batch03$Group 1 kept one brush; Group 2 kept one brush but sterilized it monthly; Group 3 got a new sterile brush monthly.$batch03$), (1, $batch03$How can it be that$batch03$, $batch03$Groups 1 and 2 had the same plaque, while Group 3 had less?$batch03$), (2, $batch03$Evaluate$batch03$, $batch03$Two results must fit. Sterilizing did nothing (1 = 2), so germs on the brush are not the cause. What is different about Group 3? Their brushes were *new*. Something about a new brush, other than being germ-free, must reduce plaque.$batch03$), (3, $batch03$Goal$batch03$, $batch03$Find a property of new brushes, not sterility, that reduces plaque.$batch03$)) v(position,label,body) WHERE q.qid=$batch03$PT122-S1-Q2$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch03$A$batch03$, $batch03$If bacteria on old brushes speed up plaque, sterilizing should have helped Group 2. But Groups 1 and 2 ended up the same.$batch03$), ($batch03$B$batch03$, $batch03$New bristles are stiff, and brushing wears that stiffness down over months. Only Group 3 always had stiff bristles. Groups 1 and 2 brushed with worn brushes, sterilized or not, so they matched.$batch03$), ($batch03$C$batch03$, $batch03$A new way of measuring plaque applies to all three groups and cannot separate them.$batch03$), ($batch03$D$batch03$, $batch03$If some of Group 3 used to brush less, they should have *more* plaque, not less.$batch03$), ($batch03$E$batch03$, $batch03$Equal vigor rules out one difference but does not explain the result.$batch03$)) v(letter,body) WHERE q.qid=$batch03$PT122-S1-Q2$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
